    public var currentTerms: String { pick("Current terms", "Conditions actuelles", "Aktuelle Bedingungen", "Condizioni attuali", "Cundiziuns actualas") }
    public func tipCompare() -> Tip { Tip(lead: pick("Two legitimate roads; the figures decide, not the brochure.", "Deux voies légitimes ; ce sont les chiffres qui décident, pas la brochure.", "Zwei legitime Wege; die Zahlen entscheiden, nicht der Prospekt.", "Due vie legittime; decidono le cifre, non l'opuscolo.", "Duas vias legitimas; las cifras decidan, betg il prospect."), bullets: [pick("Account: the money stays yours and comes back; it is just locked", "Compte : l'argent reste le vôtre et revient ; il est seulement bloqué", "Konto: das Geld bleibt Ihres und kommt zurück; es ist nur gesperrt", "Conto: i soldi restano vostri e tornano; sono solo bloccati", "Conto: ils daners restan Voss e returnan; els èn mo bloccads"), pick("Insurance: the capital stays free; premiums are normally non-refundable under current terms", "Assurance : le capital reste libre ; les primes sont en principe non remboursables selon les conditions actuelles", "Versicherung: Das Kapital bleibt frei; Prämien sind nach aktuellen Bedingungen in der Regel nicht rückzahlbar", "Assicurazione: il capitale resta libero; secondo le condizioni attuali i premi di regola non sono rimborsabili", "Assicuranza: il chapital resta liber; tenor las cundiziuns actualas na vegnan premias per regla betg restituidas"), pick("Insurance is no waiver: damages stay owed, the insurer pays and recovers from you", "L'assurance n'exonère pas : les dégâts restent dus, l'assureur paie puis se retourne contre vous", "Die Versicherung befreit nicht: Schäden bleiben geschuldet, der Versicherer zahlt und holt es bei Ihnen", "L'assicurazione non esonera: i danni restano dovuti, l'assicuratore paga e si rivale su di voi", "L'assicuranza na libera betg: donns restan debitads, l'assicuradur paja e sa regressa tar Vus"), pick("Prices and conditions change; verify them on the provider's site before choosing", "Les prix et conditions changent ; vérifiez-les sur le site du prestataire avant de choisir", "Preise und Bedingungen ändern sich; vor der Wahl auf der Website des Anbieters prüfen", "Prezzi e condizioni cambiano; verificateli sul sito del fornitore prima di scegliere", "Pretschs e cundiziuns sa midan; controllai els sin la pagina dal purschider avant da tscherner")]) }
