    public var backupPasswordBody: String { pick("Use at least 12 characters. Limen cannot recover this password; keep it separately from the backup.", "Utilisez au moins 12 caractères. Limen ne peut pas récupérer ce mot de passe; conservez-le séparément de la sauvegarde.", "Mindestens 12 Zeichen verwenden. Limen kann dieses Passwort nicht wiederherstellen; getrennt von der Sicherung aufbewahren.", "Usate almeno 12 caratteri. Limen non può recuperare questa password; conservatela separatamente dal backup.", "Duvrai almain 12 segns. Limen na po betg restabilir quest pled-clav; al tegnair separà da la segirezza.") }
    public var restorePasswordBody: String { pick("Enter the password used when this backup was created. Legacy ZIP backups are still accepted with any non-empty entry.", "Saisissez le mot de passe utilisé lors de la création. Les anciennes sauvegardes ZIP restent acceptées avec toute saisie non vide.", "Das beim Erstellen verwendete Passwort eingeben. Ältere ZIP-Sicherungen werden weiterhin mit einer beliebigen nicht leeren Eingabe akzeptiert.", "Inserite la password usata alla creazione. I vecchi backup ZIP restano accettati con qualsiasi testo non vuoto.", "Endatai il pled-clav duvrà tar la creaziun. Segirezzas ZIP veglias vegnan anc acceptadas cun mintga endataziun betg vida.") }
