    public var welcomeLead: String { pick("Limen records the apartment handover, from the first meter reading to a final PDF both sides receive.", "Limen consigne l'état des lieux, du premier relevé au PDF final remis aux deux parties.", "Limen hält die Wohnungsübergabe fest, vom ersten Zählerstand bis zum finalen PDF für beide Seiten.", "Limen registra la consegna dell'alloggio, dalla prima lettura al PDF finale ricevuto da entrambe le parti.", "Limen documentescha la surdada da l'abitaziun, da l'emprima letga fin al PDF final per omaduas partidas.") }
    public func stepLead(_ step: FlowStep) -> String {
        switch step {
        case .hub: return pick("Two halves, in whatever order suits you: what you can see and touch, and what is on paper.", "Deux moitiés, dans l'ordre qui vous convient : ce qui se voit et se touche, et ce qui est sur papier.", "Zwei Hälften, in beliebiger Reihenfolge: was sichtbar und greifbar ist, und was auf dem Papier steht.", "Due metà, nell'ordine che preferite: ciò che si vede e si tocca, e ciò che è sulla carta.", "Duas mitads, en l'urden che vus vulais: quai ch'ins vesa e tutga, e quai ch'è sin palpiri.")
        case .inspection: return pick("Go through the flat in your own order. Confirm every listed room after checking it, even when there is no defect.", "Parcourez le logement dans l'ordre qui vous convient. Confirmez chaque pièce après contrôle, même sans défaut.", "Gehen Sie in Ihrer eigenen Reihenfolge durch. Bestätigen Sie jeden aufgeführten Raum nach der Prüfung, auch ohne Mangel.", "Percorrete l'alloggio nell'ordine che preferite. Confermate ogni locale dopo il controllo, anche senza difetti.", "Giai tras l'abitaziun en voss agen urden. Confermai mintga local suenter la controlla, era senza mancanzas.")
        case .objects: return pick("Use one row per supplied item, confirm its condition and add a clear photo when useful.", "Utilisez une ligne par objet fourni, confirmez son état et ajoutez une photo nette si utile.", "Verwenden Sie je mitgeliefertem Gegenstand eine Zeile, bestätigen Sie den Zustand und fügen Sie bei Bedarf ein klares Foto hinzu.", "Usate una riga per ogni oggetto fornito, confermatene lo stato e aggiungete una foto chiara se utile.", "Duvrai ina lingia per mintga object furnì, confermai ses stadi ed agiuntai ina foto clera sche util.")
        case .dossier: return pick("The paperwork around the handover. Add a component only when this handover has it.", "Les documents autour de la remise. N'ajoutez une rubrique que si elle concerne cette remise.", "Das Papier rund um die Übergabe. Fügen Sie eine Rubrik nur hinzu, wenn sie diese Übergabe betrifft.", "I documenti attorno alla consegna. Aggiungete una rubrica solo se riguarda questa consegna.", "Ils documents enturn la surdada. Agiuntai ina rubrica mo sch'ella pertutga questa surdada.")
        case .review: return pick("Read the findings aloud together and record each side's position. Signing does not decide liability or payment.", "Relisez les constats ensemble et consignez la position de chacun. La signature ne décide ni la responsabilité ni le paiement.", "Gehen Sie die Befunde gemeinsam durch und halten Sie beide Positionen fest. Die Unterschrift entscheidet weder Haftung noch Zahlung.", "Rileggete insieme i rilievi e registrate la posizione di ciascuno. La firma non decide responsabilità o pagamento.", "Legì ils resultats ensemen e registrai la posiziun da mintga vart. La suttascripziun na decida betg responsabladad u pajament.")
        case .sign: return pick("Review who must sign or refuse the handover record and record any reservation first.", "Vérifiez qui doit signer ou refuser le constat et consignez d'abord toute réserve.", "Prüfen Sie, wer das Übergabeprotokoll unterzeichnet oder verweigert, und erfassen Sie Vorbehalte zuerst.", "Verificate chi deve firmare o rifiutare il verbale e registrate prima ogni riserva.", "Controllai tgi che sto suttascriver u refusar il protocol e registrai l'emprim mintga resalva.")
        case .export: return pick("Export the PDF and hand a copy to each side right now.", "Exportez le PDF et remettez un exemplaire à chaque partie immédiatement.", "Exportieren Sie das PDF und übergeben Sie jeder Seite sofort ein Exemplar.", "Esportate il PDF e consegnate subito una copia a ciascuna parte.", "Exportai il PDF e surdatti immediat ina copia a mintga vart.")
        }
